"""Editable curriculum. Build static, authenticated HTML with scripts/build.py."""
BOOKS = []
def book(letter, slug, title, track, goal, free, paid, steps, example, fixes, next_books):
    BOOKS.append(dict(letter=letter, path=f'playbooks/playbook-{letter.lower()}-{slug}.html', title=title, track=track, goal=goal, free=free, paid=paid, steps=steps, example=example, fixes=fixes, next=next_books))
def step(title, action, prompt, output, check):
    return dict(title=title, action=action, prompt=prompt, output=output, check=check)

book('A','land-first-client','Find and pitch your first service client','service',
 'Finish with one scoped offer, ten researched prospects, a tailored sample, and a tracked outreach sequence. A seven-day work plan, not a promised client deadline.',
 ['ChatGPT or Claude Free for drafting. Google Maps and public business profiles for research. Google Sheets for tracking. Canva Free for a sample.', 'Start with five careful messages per work session. Follow platform rules, stop after a refusal, and avoid automated blasts. No subscription is required.'],
 ['Claude Pro is optional for longer client context and heavier drafting. Use the same brief and quality checks as the free route.', 'A paid research agent is optional. Ask for linked evidence and check each prospect yourself. Upgrade only when saved time exceeds cost.'],
 [step('Choose an offer you can deliver','Pick content, copy, or a small lead workflow. Choose one business type you understand. Sell a defined deliverable, not guaranteed revenue. Estimate research, revisions, handoff, and costs before quoting.',
 'My skills: [skills]. My time this week: [hours]. Businesses I understand: [types]. Suggest three small service offers I can deliver competently. For each give the deliverable, required inputs, exclusions, estimated effort, and one quality check. Do not promise bookings or income. Recommend one and explain why.',
 'One offer sentence, deliverables, turnaround, and exclusions.','A stranger understands what they receive and you know how to produce it.'),
 step('Research ten prospects','Search a niche and city on Maps, then open the business website and public social profile. Note one observable issue, its source URL, and a useful improvement. An inactive feed is a clue, not proof of purchase intent. Prefer explicit requests for help.',
 'Review these public observations I collected: [business, URL, observation, date]. Rank fit for [offer]. Give a specific opener and the reason for each ranking. Mark missing evidence. Do not invent names, contact details, budgets, last-post dates, or interest in buying.',
 'Ten rows: business, URL, observation, possible help, contact route, follow-up date.','Every observation has a source you opened. Contact only through an appropriate business channel.'),
 step('Build one relevant sample','Use E for a content sample, G for copy, or I for a lead workflow. Spend a bounded session on one small example. Label unpaid work as a sample. Show the before and the proposed improvement without claiming a client result.',
 'Create a sample [deliverable] for this business using only this brief: [facts]. Explain the proposed change in three bullets. Flag assumptions and missing inputs. Keep it small enough to review in two minutes. Label it a demonstration, not commissioned work.',
 'A PDF, image, or screen recording showing one useful change.','Business details are correct. The sample contains no invented testimonial or performance metric.'),
 step('Send a permission-based message','Write a specific observation and offer to share the sample. Ask one easy question. Send manually. Record the date. Do not attach a large file or present yourself as an existing supplier.',
 'Write a business DM under 65 words. Business: [name]. Observation: [verified observation]. Sample: [what I made]. Ask permission to share it. Use a warm, direct tone. No fabricated experience, urgency, flattery, or guaranteed results. Give two alternatives.',
 'Five personalized messages logged in the Outreach Tracker.','All brackets are replaced and each message matches the business.'),
 step('Follow up and qualify replies','If there is no response, follow up after roughly three days, then once more after another three. Stop immediately after a refusal. Ask about the current problem, desired deliverable, approver, timing, and budget before quoting.',
 'Draft two polite follow-ups to [original message]. First offers one useful detail from [sample]. Second closes the loop without pressure. Also give five qualification questions for someone who replies. Never imply silence means consent or interest.',
 'Two follow-up drafts and a five-question discovery outline.','The next step is clear and the recipient has an easy exit.'),
 step('Agree scope and deliver','Send a written scope with deliverables, dates, one revision round, payment terms, and exclusions. A 50% deposit is an option to agree, not a rule. After payment confirmation, use F for delivery. Ask for feedback and permission before publishing proof.',
 'Draft a plain-language project scope from [agreed facts]. Include deliverables, required client inputs, due dates, revision limits, exclusions, payment schedule, and approval process. Mark unresolved items as questions. This is a business draft for review, not a claim of legal completeness.',
 'An approved scope and delivery checklist.','No work begins on an ambiguous brief. The quote covers your actual effort and costs.')],
 {'title':'Worked examples: a coach, repair business and online shop','body':'Compare three fictional briefs in the example library: a fitness coach explaining an introductory session, a repair business clarifying how an assessment works, and a shop showing desk-organizer dimensions. Each uses the same offer structure: seven captions, three layouts, one revision, and a clear handoff. The details, buyer question, image permissions and CTA change with the client. Sample opener: “Hi [team], your [verified page detail] gave me an idea for a short FAQ. I made a one-page demonstration from those public facts. Would you like to see it?” Choose a business type you understand; the Blueprint does not choose a niche for you.', 'asset':'content-delivery.html'},
 [('No replies','Check fit, message clarity, and whether the sample solves an observable problem. Change one variable in the next small batch. Do not treat any fixed reply ratio as normal for everyone.'),('Interested but no payment','Ask which scope, timing, or price point is unresolved. Agree a concrete next step. A verbal yes is not collected revenue.'),('No confidence in delivery','Finish the sample in F or G first. Narrow the package before taking paid work.')], ['E','F','G'])

book('B','launch-product','Build and launch a useful digital product','product',
 'Move from a narrow problem to a tested downloadable product and a working product page. Five work sessions. Sales depend on demand and distribution.',
 ['ChatGPT or Claude Free for structure. Google Docs or Canva Free for the file. One eligible storefront with no mandatory monthly subscription.', 'Use the storefront test mode where available. Confirm country support, fees, refund settings, delivery, and payouts before launch.'],
 ['Claude Pro optionally handles longer source material. Canva Pro optionally adds brand and design features. Neither replaces buyer research.', 'Spend first on a demonstrable production bottleneck. A paid subscription does not validate an idea or supply customers.'],
 [step('Find evidence of a narrow problem','Choose one buyer and one task. Collect five actual questions, review excerpts, or interview notes. Record sources and dates. Check how people solve the problem now. Ask three relevant people to react to a small sample before building.',
 'Here is actual research: [sources and observations]. Separate evidence, inference, and unknowns for [product idea]. Identify a repeated problem, current alternatives, and a narrow product promise. Suggest three interview questions. Do not infer willingness to pay from an AI score.',
 'An evidence worksheet and a one-sentence promise.','The promise is tied to a real task. At least one potential buyer reviewed a sample.'),
 step('Define the smallest complete product','Choose a template pack, focused guide, workbook, or short tutorial. List the exact assets and success criteria. Include instructions, a worked example, and a checklist. Avoid a broad course generated from an outline alone.',
 'Design a minimum complete [format] for [buyer] to do [task]. Use [research]. Output an asset list, section outline, a ten-minute first task, one filled example, and quality criteria. Flag anything requiring specialist expertise or verification.',
 'A product specification you can inspect before writing.','The buyer knows how to start and what a finished result looks like.'),
 step('Produce and review every asset','Draft one section at a time. Edit generic advice. Test each template yourself using real or clearly fictional inputs. Export, open on mobile, and check links. Inspect the filled product in the Example chapter as a reference.',
 'Write section [section] using [verified inputs]. Include exact actions, one filled example, and a pass/fail check. Avoid invented statistics. Mark missing information. Then critique the draft for vague advice, unsupported claims, and steps a beginner cannot execute.',
 'A complete PDF or template pack with instructions.','You followed the instructions and reached the stated output. No placeholder remains in the buyer file.'),
 step('Set price and delivery','Compare a few relevant offers using live sources. Choose an introductory price as a test, not a market fact. Document fees and net receipts. Configure one-time or recurring billing correctly and show refund terms you will honor.',
 'Use these competitor observations: [URLs, prices, inclusions, dates]. Compare my product [assets]. Suggest three test prices with reasoning. Calculate gross and net under [verified fees]. Distinguish one-time payment from subscription. Do not invent competitor claims.',
 'A pricing rationale and configured checkout.','Billing matches the product promise and the buyer receives the right file.'),
 step('Write and test the product page','Show the outcome, buyer, contents, sample, limitations, price, and refund policy. Include authentic proof if you have it. Test checkout and receipt delivery in the platform test environment. A self-purchase and refund do not prove a payout schedule.',
 'Write a concise product page for [product] using [verified contents]. Include buyer, problem, outcome, exact inclusions, screenshot suggestion, price, access instructions, actual refund policy, and one CTA. No invented students, income results, scarcity, or endorsements.',
 'A working page, sample preview, and delivery test.','A new visitor understands what they buy and how to use it.')],
 {'title':'Worked example: the Freelancer Project Starter','body':'A reusable brief and delivery planner for freelancers: quick-start instructions, a filled landing-page-copy example, a blank client brief, scope worksheet, asset checklist, approval message and review log. The outcome is organizing a small project, not finding guaranteed clients. The complete printable product below shows every part. A practice $19 price is a test assumption; ten sales would be $190 gross before fees, refunds and costs. Confirm demand with likely buyers before producing your own pack.', 'asset':'freelancer-project-starter.html'},
 [('AI likes the idea, buyers do not','Interview people and inspect alternatives. Replace the assumption with evidence or narrow the task.'),('Traffic but no purchases','Check buyer fit, page clarity, sample quality, checkout, and objections. Improve one item before generating another product.'),('Buyer cannot use the file','Add a quick-start page and filled example. Test with someone unfamiliar with the product.')],['C','E','I'])

book('C','faceless-funnel','Produce a week of faceless demonstration videos','both',
 'Produce seven scripts, one reusable edit, and a tracked posting plan showing a real product or service result.',
 ['Record your screen and your own voice. Use your own footage or Pexels clips. Edit with available free features in VN or CapCut; create slides in Canva Free.', 'Check every selected feature and export before a batch. If captions require a paid tier, type and time them manually. Use licensed audio suitable for the account and intended use.'],
 ['Claude Pro optionally helps script larger batches. Higgsfield optionally supplies generated scene inserts. Keep screen demonstrations as the evidence.', 'Calculate credits per usable scene and retries before subscribing. Build a storyboard first. Generated people are not customer testimonials.'],
 [step('Pick one observable transformation','Use a result you can show: a blank calendar becomes seven usable posts, or a vague headline becomes clear copy. Record the finished output first so your hook has a real payoff. Avoid unverified revenue or engagement claims.',
 'My offer is [offer]. I can demonstrate [finished output]. Give five before/after video angles for [audience]. Each must be truthful, specific, and visible on screen. Exclude income promises and claims I cannot demonstrate.',
 'One before-and-after sentence and a proof shot.','The footage supports the hook without relying on a fictional result.'),
 step('Write seven useful scripts','Use a hook, problem, short demonstration, and next step. Mix mistakes, walkthroughs, comparisons, and FAQs. Keep the voiceover short enough to match your natural speaking speed. Read each out loud before recording.',
 'Create seven 25-40 second scripts for [audience] about [offer]. Source material: [verified process]. Mix two mistakes, two tutorials, one comparison, one FAQ, one demonstration. For each provide voiceover, scene sequence, on-screen text, and one CTA. No invented proof.',
 'Seven scripts with a shot list for each.','Each teaches or demonstrates one useful action rather than repeating a sales pitch.'),
 step('Capture a reusable footage bank','Record five clean clips: brief, prompt, output, edits, and final deliverable. Hide account details. Record with a readable zoom. For stock, search the specific action, inspect the license, and keep source links. Do not pretend stock shows a client.',
 'Turn [script] into a shot list. Label each shot SCREEN, OWN FOOTAGE, STOCK, or GENERATED. Give duration, what it proves, and text overlay. Prioritize actual output. Include a stock search phrase only when needed.',
 'A labeled folder of source clips and assets.','The screen remains readable in a phone preview and every visual has a clear role.'),
 step('Build one complete edit','Create a 1080×1920 project. Place the payoff early, then show key steps. Add captions, check spelling and safe margins, balance voice/music, and export. Use still-image motion if you do not need video generation.',
 'Review this edit plan: [timestamps and scenes]. Identify slow openings, missing explanation, unreadable text, and mismatches between speech and visuals. Suggest specific cuts. Keep the finished demonstration and a single next step.',
 'One finished vertical video and a reusable project.','The video makes sense muted and spoken claims match the screen.'),
 step('Publish and track buyer actions','Schedule one useful piece daily. Reuse the clean original across platforms. Record reach, profile visits, attributable clicks, conversations, and sales. Compare rates as well as totals. Treat the first seven posts as a learning batch.',
 'Analyze these actual post metrics: [rows]. Separate reach problems, click problems, and purchase problems. Suggest one change for the next batch and explain uncertainty from the small sample. Do not claim views imply sales.',
 'Seven posts and a filled Daily Content Tracker.','You have an explicit numerator and denominator for each rate. Missing metrics stay blank, not invented.')],
 {'title':'Worked example: show a useful transformation','body':'Record a blank brief becoming an approved content plan, a vague repair-service headline becoming a clear assessment CTA, or an empty project worksheet becoming a reusable product. Use the same sequence: final output for 0–3 seconds, real inputs for 3–8, one prompt for 8–13, draft versus edit for 13–22, finished file for 22–30, and one next step. Label practice inputs and demonstrate the work. The seven-script download gives multiple angles without choosing one niche for everyone.', 'asset':'seven-video-scripts.txt'},
 [('Views but no clicks','Check whether the audience, demonstrated output, and offer match. Show the next step clearly and make the profile link understandable.'),('No footage','Use the sample pack and record the process. Three readable screen shots beat unrelated filler.'),('Production is slow','Reuse footage and layout. Batch voiceovers. Generate only the scene you cannot record.')],['E','H','I'])

book('D','scale-to-2k','Build a profitable, repeatable delivery system','both',
 'Calculate delivery capacity, improve margins, and plan retention from actual sales data. $2,000 is a planning target, not a forecast.',
 ['Use the Weekly Scorecard, Google Sheets, saved prompts, and delivery templates. Record costs and hours for every project.', 'Ask existing satisfied clients for feedback and referrals. Publish genuine examples with permission.'],
 ['Use Claude Pro only if longer reusable context saves measured time. Upgrade creative tools for a proven recurring deliverable.', 'Set a tool budget from collected revenue and capacity. Avoid buying automation before documenting a working process.'],
 [step('Measure your current economics','Record collected revenue, processing fees, refunds, subscriptions, delivery hours, and outreach hours. Separate pipeline from money received. Compare net contribution per project and repeat purchase rate.',
 'Analyze this real weekly data: [revenue, fees, refunds, tools, hours, projects]. Calculate net contribution and effective hourly return. Show formulas and missing inputs. Separate collected money, invoiced money, and pipeline. Do not forecast from one week.',
 'A filled weekly scorecard and cost baseline.','Every number has a source and profit is not confused with gross sales.'),
 step('Fix the delivery bottleneck','List steps you repeat. Standardize intake, brief, drafting, QA, and handoff using F. Time a second delivery using the template. Keep the work client-specific and do not reuse confidential material across clients.',
 'Turn my actual workflow [steps and durations] into an SOP. Give input, action, output, owner, and quality check for each stage. Suggest two simplifications. Do not remove client approval or verification to save time.',
 'One tested delivery SOP and measured time saving.','A second project follows the process without losing quality.'),
 step('Test a better package or price','Improve scope and evidence before changing prices. Quote new work based on delivery cost, demand, and value. Honor existing agreements. Test one change rather than assuming a fixed percentage increase works.',
 'Current offer: [scope, price, costs, hours]. Buyer feedback: [actual feedback]. Propose three revised packages with explicit inclusions, exclusions, capacity, and margin. Draft a clear new-client quote. Do not invent scarcity or ROI.',
 'A revised package with a price floor.','The price covers the work and the promised scope fits your weekly capacity.'),
 step('Offer continuity where it helps','A retainer fits recurring needs, not every project. Show what happens every month, reporting, revisions, payment schedule, and cancellation terms. Review performance with the client before proposing ongoing work.',
 'Draft a recurring proposal for [client need] using [delivered work and results]. Include monthly outputs, reporting, boundaries, cancellation, price, and review date. Make no guarantee of sales or platform reach.',
 'One recurring proposal tied to an actual need.','The ongoing value is clear without repeating a one-off deliverable.'),
 step('Grow within capacity','Choose one proven acquisition channel. Increase volume only while delivery stays reliable. Add another offer after the first is documented and profitable. Estimate how many clients or units reach the target and how much work they require.',
 'I have [hours] per week. A client takes [hours] and pays [price], with [costs]. Calculate feasible clients, gross revenue, and net contribution. Compare with [product units and price]. Identify the bottleneck and a conservative next experiment.',
 'A capacity-aware growth plan and weekly review.','Your target uses actual delivery capacity, fees, and costs, not optimistic headline math.')],
 {'title':'Worked example: four recurring clients','body':'Planning scenario, not a student result: four clients paying $500 produce $2,000 gross monthly revenue. If direct monthly costs are $200 and total delivery plus acquisition time is 40 hours, contribution before tax and other overhead is $1,800, or $45 per hour. If revisions double the time, the hourly result halves. A smaller, clearly scoped retainer often improves reliability more than adding a second income stream immediately.', 'asset':'weekly-scorecard.csv'},
 [('Revenue rises but you are exhausted','Measure revision and communication hours. Tighten scope, improve intake, or reduce client count.'),('One client supplies most income','Keep prospecting and build a cash buffer. Do not treat a single renewal as stable demand.'),('You want to add five offers','Document one profitable workflow first. Add only the complementary offer customers repeatedly request.')],['F','I','A'])

book('E','carousel-leads','Build Instagram carousels around a useful result','both',
 'Create a seven-slide carousel, a coherent caption, and a clear lead path. Use it for your offer or as a client deliverable.',
 ['Draft with ChatGPT or Claude Free. Design in Canva Free at 1080×1350. Use owned imagery or relevant Pexels photos, and use only free elements.', 'Duplicate pages, vary the layout, and export PNG. Review each slide at phone size before posting.'],
 ['Claude Pro optionally helps adapt a longer source document. Canva Pro optionally supplies brand controls and licensed assets.', 'Higgsfield is optional for a visual demonstration illustration. Use real output screenshots as evidence and disclose generated scenes where relevant.'],
 [step('Choose one reader and one decision','Pick a question your buyer faces: how to find a prospect, how to write a caption, or what goes in a client pack. Make the carousel solve one part of the problem. Choose one next step suited to the content.',
 'Reader: [specific situation]. Problem: [problem]. Offer: [offer]. Give five carousel angles teaching one useful action. For each identify the demonstration, desired reader action, and honest hook. No claims about algorithm preference or guaranteed reach.',
 'One carousel brief with reader, promise, and CTA.','The reader gains something useful even without buying.'),
 step('Write seven slides with a payoff','Open with a clear tension. Show the mistake, method, worked example, and next action. Keep one idea per slide. Use short headings and only the supporting text necessary to understand the action.',
 'Write seven slides from [source]. Structure: hook, mistake, step one, step two, filled example, checklist, CTA. Each heading under ten words, body under 35 words. Suggest a visual for each. Ground every claim in the supplied evidence.',
 'A seven-slide script and visual plan.','The sequence is useful in order, with no duplicate point or unsupported result.'),
 step('Set a small design system','In Canva create a custom 1080×1350 design. Pick two font families, two brand colors plus a neutral, and a consistent label. Use large readable headlines and safe margins. Build text, photo, screenshot, and comparison layouts.',
 'For this seven-slide script [script], propose a layout per slide using text-only, screenshot, photo-overlay, or before/after. State hierarchy, emphasis, and whitespace. Avoid repeating the same heading position. Prioritize phone readability.',
 'Four reusable page layouts and a consistent style.','Text contrasts with the background and each layout serves its content.'),
 step('Add actual evidence and export','Place the prompt screenshot, tracker row, or final output where it teaches the method. Crop account details. Use a dark overlay on busy photos. Download all pages as PNG, inspect order, and open them on a phone.',
 'Review this slide copy and visual plan [details]. Flag vague teaching, small text risk, missing context, duplicated layouts, and unverifiable claims. Give exact replacements. Keep source screenshots as the evidence.',
 'Seven correctly ordered images and one caption.','Every image is legible, licensed, and consistent. No person in stock imagery is presented as a customer.'),
 step('Connect the carousel to a lead path','Use I to deliver a useful sample manually or through an eligible automation tool. If asking people to comment a keyword, have a working response process. Record profile visits, saves, clicks, conversations, and purchases where available.',
 'Write a caption for [carousel] and a manual response to someone requesting [sample]. Be clear about what they receive. Use one CTA. Add a follow-up question only after delivering the requested resource. Do not imply automation exists if it does not.',
 'A published carousel and a verified sample-delivery process.','The next step works and you measure buyer actions without assuming saves equal sales.')],
 {'title':'Worked example: from a vague draft to a useful output','body':'Slide 1: “Would you pay for this AI draft?” Slide 2: Show a vague line with unsupported claims. Slide 3: Show the confirmed brief. Slide 4: Rewrite it for one reader question. Slide 5: Show the coach, repair-service and shop versions side by side. Slide 6: Check facts, rights, CTA and handoff. Slide 7: Offer the public preview. The full storyboard below includes text and layout instructions. Use screenshots of your actual output, not invented client results.', 'asset':'carousel-storyboard.txt'},
 [('Lots of words on each slide','Cut the slide to one decision and move supporting detail to the caption or linked guide.'),('Pretty but no teaching','Insert a filled example and show why you changed the output.'),('No leads','Check buyer relevance and sample delivery. Compare actions per reach across several posts rather than one.')],['F','I','C'])
book('F','content-service','Deliver a complete social content service','service',
 'Complete a content-service delivery: intake, plan, captions, layouts, QA, handoff and review. Compare three different client types, then use the process for a business you understand.',
 ['ChatGPT or Claude Free, Google Docs/Sheets, Canva Free, and client-owned photos. Start with seven posts and three designs.', 'Pexels is a fallback for illustrative imagery. Confirm free elements and download your work before promising a format.'],
 ['Claude Pro optionally stores longer brand context. Canva Pro optionally adds brand controls and approved premium elements.', 'Higgsfield optionally creates scene inserts from approved product images. Agree asset rights and production costs separately.'],
 [step('Collect a usable client brief','Ask for services, prices, opening hours, target audience, booking link, brand voice, approver, approved photos, and prohibited claims. Clarify who posts and who answers messages. Use the blank brief download with the filled example in the Example chapter. Complete it with confirmed client facts first.',
 'Turn this intake [facts] into a one-page content brief. Separate confirmed facts, assumptions, and questions. Include brand voice, audience, services, CTA, available photos, approval contact, and exclusions. Stop and ask questions if the booking link or offer details are missing.',
 'An approved brief with every essential detail.','The client confirms the information you will publish.'),
 step('Plan seven posts with different jobs','Give each post a purpose: explain a service, answer a question, show a process, or invite a booking inquiry. Use a mix of useful education and relevant promotion. Match topics to available photos. Do not claim an arbitrary posting frequency creates bookings.',
 'From [approved brief], create a seven-day calendar. Columns: day, topic, reader question, format, visual asset, caption angle, CTA, approval status. Use confirmed services only. Vary the job of each post. Do not invent promotions or before/after results.',
 'Seven calendar rows ready for client review.','Every post has a distinct purpose and a feasible visual.'),
 step('Draft and improve the captions','Draft from the approved facts. Replace generic praise with specific useful guidance. Read aloud. Verify prices, spelling, dates, contact information, and business claims. Keep the client voice consistent. Show one raw-to-edited example in the pack.',
 'Write captions for [approved calendar] using [brief]. Each has a clear first line, two useful detail sentences, and one CTA. Then audit every factual claim against the brief. Mark unsupported details rather than filling them in. Provide an edited version and explain changes.',
 'Seven captions plus a claim check.','A reader knows what to do next and every business fact matches the brief.'),
 step('Build three reusable designs','Create one service card, one FAQ graphic, and one process post in Canva. Use client photos where possible. Set the size, margins, contrast, typography, and logo placement. Export PNG and provide editable access only under agreed sharing terms.',
 'Give three Canva design briefs from [calendar]. For each specify headline, supporting text, photo, layout, emphasis, and export format. Use a clear hierarchy and short text. Do not add unapproved discounts or performance claims.',
 'Three finished designs and source files.','The client sees the correct business identity and all text is readable on mobile.'),
 step('Package and hand off','Create folders for brief, calendar, captions, designs, and instructions. Include posting order, filenames, and one revision form. Record a short walkthrough showing how to use the pack. Deliver on the agreed date and log approval.',
 'Write a handoff message for [client] with [deliverables]. Explain where files live, suggested posting order, who posts, how to request the agreed revision, and the approval deadline. Add a three-minute walkthrough outline. Keep it clear and practical.',
 'A complete delivery folder and approval request.','The owner can use the pack without another explanation call.'),
 step('Report and propose the next scope','Collect actual reach, clicks, and inquiries if you have access. Say which metrics are unavailable. Ask what the owner found useful. Propose a recurring package only if there is an ongoing need. Ask permission to feature the work and quote feedback.',
 'Write a weekly report from [actual metrics]. Separate observed outcomes from assumptions. Summarize delivered assets, client feedback, and one next experiment. If tracking is missing, state that. Do not attribute every booking to social content.',
 'A factual report and an optional next-month scope.','No invented uplift or causal claim appears in the report.')],
 {'title':'Complete walkthrough: three business briefs, one delivery process','body':'Choose the coach, repair business or online shop in the worked example. Each has a complete brief, seven calendar rows, seven captions, three layouts, a raw-to-edited comparison, QA and handoff. Compare what changes between buyers and what stays constant in the delivery process. All names and facts are fictional. Create your own pack using verified inputs and owner-approved assets. Completion means the recipient can use the files without asking you to explain the basics.', 'asset':'content-delivery.html'},
 [('Client gives no photos','Ask for an approved phone photo set or agree an illustrative stock route. Do not invent product or treatment results.'),('Too many revisions','Use one approver, explicit acceptance criteria, and the agreed revision round. Quote new scope separately.'),('AI tone sounds generic','Supply sample client captions and edit the first line into specific customer language.')],['A','E','D'])

book('G','copywriting-project','Sell and deliver a focused copywriting project','service',
 'Rewrite one homepage section and a three-email follow-up sequence using verified business facts. Package the before/after and delivery instructions.',
 ['ChatGPT or Claude Free, Google Docs, and the business’s current page. Offer copy delivery without website implementation unless agreed.', 'Use a short Google Doc sample. No paid design or automation tool is needed for the first project.'],
 ['Claude Pro optionally handles longer research and voice references. Use the same evidence checks and final human edit.', 'Paid testing or email tools are relevant only when the client already needs deployment and has agreed the additional scope.'],
 [step('Choose one page and one action','Select a small project: hero section, booking page, or three follow-up emails. Ask who the reader is and what action they should take. Collect current copy, service details, genuine proof, and objection notes.',
 'Audit this copy [copy] for [reader] seeking [goal]. List unclear promises, missing specifics, weak CTA, and claims needing evidence. Recommend one small project scope. Do not infer conversion rates or revenue lost.',
 'A copy brief and three observable problems.','The scope names the page sections and excludes development if you are only writing.'),
 step('Build a message hierarchy','Identify the buyer problem, relevant outcome, reason to trust, and next step. Use customer language from actual interviews or reviews. Never copy competitors verbatim or invent testimonials.',
 'Using only [business facts and customer language], build a message hierarchy: audience, problem, offered service, differentiator, verified proof, CTA, and objections. Mark any unsupported promise. Give three headline directions.',
 'A positioning outline and headline options.','Each line has a factual basis and the claim fits the business capability.'),
 step('Draft a before/after sample','Rewrite the hero and one supporting section. Explain what changed and why. Use deliverable-focused copy without promising an exact sales lift. Show the original and your proposed version for comparison.',
 'Rewrite this hero [original] using [approved hierarchy]. Output headline, subheadline, three benefit bullets, CTA, and a short explanation of each change. Avoid vague adjectives, invented proof, and guarantees. Label the result proposed copy.',
 'A readable before/after document.','The new text answers who, what, why, and next step in seconds.'),
 step('Write a three-email sequence','For opted-in leads or customers, draft delivery/value, problem-and-solution, and invitation-to-act emails. Use the client’s actual consent and unsubscribe process. Do not imply cold contacts subscribed.',
 'Write three follow-up emails for [consented audience] about [offer]. Email one delivers [requested resource]. Two explains a useful step. Three offers [actual next step]. Include subject, preview text, body, and CTA. No false scarcity or fabricated outcomes.',
 'Three edited emails and sending conditions.','Each message delivers on the reason the recipient opted in.'),
 step('Review and deliver','Check names, claims, links, tone, and reading flow. Include source notes for factual claims. Ask for one approval pass. Provide a document with placement instructions and versions. If the client tests it, record the actual data and uncertainty.',
 'QA this copy [draft] against [approved facts]. Return incorrect facts, unsupported claims, unclear wording, broken placeholders, and inconsistent CTAs. Give exact revisions. Produce a placement guide and approval questions.',
 'Final copy, placement guide, and approval record.','The client knows where each section belongs and no placeholder goes live.')],
 {'title':'Worked example: a fictional consultation business','body':'Original: “We offer world-class solutions for your future.” Proposed: “Plan your university applications with a clear next step.” Subheadline: “Book a consultation to review your study goals, documents, and application timeline.” CTA: “Book a consultation.” This is practice copy, not a visa or admission guarantee. The downloadable example adds three follow-up emails and a claim-review checklist.', 'asset':'copy-project.txt'},
 [('Client asks for a sales guarantee','Guarantee only deliverables or an agreed correction process you control. Sales depend on factors outside the copy.'),('No customer research','Ask for actual questions from inquiries and anonymized objection notes. Label untested hypotheses.'),('You are asked to build the site too','Define implementation as separate scope with its own cost and acceptance checks.')],['A','I','D'])

book('H','ai-video-creative','Produce product video creative with a controlled budget','service',
 'Complete one 30-second product creative: brief, storyboard, free edit or AI scene route, three hook variants, and a client handoff.',
 ['Use client-owned product footage or film your own hands-on demo. Add licensed stock only for context. Write with ChatGPT or Claude Free and edit in available free VN/CapCut features.', 'If you cannot access the product, offer a storyboard or illustrative concept rather than claiming a genuine product-use demonstration.'],
 ['Claude Pro optionally expands the script and storyboard. Higgsfield optionally generates short scene inserts from an approved product image.', 'Higgsfield prices and model access vary by plan. Read the current monthly card, available credits, and Generate-button cost. Use the capacity calculator under Tools before quoting. Web unlimited access is model-specific and does not apply to automated generations.'],
 [step('Agree the creative brief and rights','Define audience, product, goal, platform, duration, approved claims, reference style, music rights, image rights, usage, and revision count. Ask whether synthetic scenes are acceptable. Offer creative production, not guaranteed leads.',
 'Turn [client facts] into a 30-second creative brief. Include audience, problem, approved product benefits, CTA, usage, deliverables, revisions, and asset rights. List missing facts and claims requiring evidence. Do not invent customer experiences.',
 'An approved brief and asset folder.','You have permission to use the product images, identity, voice, and audio.'),
 step('Storyboard before generating','Write a six-shot story: hook, problem, product, demonstration, detail, CTA. Separate real evidence from illustrative scenes. Give duration, text, and motion for each shot. Design three hooks around one consistent body.',
 'Storyboard a 30-second video from [brief]. Six shots with time, visual source, voiceover, text overlay, and action. Label REAL DEMO or ILLUSTRATION. Provide three truthful hooks. Keep product labels and claims unchanged.',
 'Six-shot storyboard and three hook variants.','Every shot has a purpose and the product claim is supported.'),
 step('Build the free route first','Record close-ups with steady light and a plain background. Use licensed stock for context, never as false product evidence. Place shots in the editor, record voice, add captions, and export a rough cut before considering AI.',
 'Adapt [storyboard] to a no-subscription production plan. Use own screen/product footage, still-image movement, and licensed stock. Give exact shot substitutions, recording instructions, and edit order. Preserve the original claims.',
 'One rough edit made without an AI video subscription.','The product is recognizable and the demonstration is honest.'),
 step('Generate only the missing scenes','For the paid route, upload approved assets into a currently available Higgsfield image/video workflow. Generate a short test at the intended ratio. Check labels, anatomy, motion, and consistency before more attempts. Stop when the scene budget is used.',
 'Create a short image-to-video prompt from [approved product image description]. Scene: [scene]. Camera: [one movement]. Duration: [duration]. Preserve label, product shape, and brand colors. Natural lighting. Do not add new claims, extra products, or fake testimonials. Give a simpler fallback.',
 'One accepted scene with actual credits and attempts logged.','You inspect the output frame by frame and reject altered labels or invented demonstrations.'),
 step('Edit, export, and package variants','Combine approved scenes with the real demonstration. Add voice, captions, licensed music, and the CTA. Export 1080×1920 for the agreed platform. Package three opening variants, one main body, source notes, and a handoff guide.',
 'Create a delivery checklist for [agreed creative]. Include duration, ratio, captions, spelling, claim accuracy, product consistency, music license, variants, filenames, and client approval. Add a handoff note explaining which shots are generated.',
 'Three finished hook variants and a documented delivery.','The client understands what was generated and what was recorded.')],
 {'title':'Worked example: a fictional desk organizer','body':'30-second concept: 0–3s show a cluttered desk, 3–7s name the difficulty finding small items, 7–13s show the real organizer and its compartments, 13–20s record placing pens and notes inside, 20–26s use an illustrative slow product push-in, 26–30s show the product page CTA. The paid scene prompt keeps the product shape and label intact. Budget illustration: 1,000 credits, 10 credits per attempt, three attempts per accepted shot, two generated shots per edit gives floor(1000 / 60) = 16 edits before image or upscale costs. These inputs are hypothetical, not a live subscription allowance. Use the calculator with your actual plan.', 'asset':'video-storyboard.csv'},
 [('Generations distort the product','Use the real photo or filmed footage. A still with subtle movement is a valid final scene.'),('Credits disappear quickly','Reduce generated shots, retries, or resolution. Log actual cost. Account for image generation and upscaling too.'),('No leads from the creative','Check offer, audience, landing page, and lead follow-up. Creative delivery alone does not establish campaign results.')],['C','I','D'])

book('I','lead-follow-up','Build a working sample-to-sale follow-up path','both',
 'Deliver a requested sample, qualify interest, show a working checkout or service proposal, and track each step.',
 ['Use a public sample link, manual replies, and the existing storefront. Record conversations in Sheets. Collect only the details needed to respond.', 'Start manual so you understand the questions before adding an automation tool. Send the resource people asked for before pitching.'],
 ['Use an eligible paid messaging/email tool only after checking current platform permissions, costs, and contact limits.', 'Claude Pro optionally drafts variations from actual objections. A paid automation platform speeds a working conversation, not an unclear offer.'],
 [step('Create one useful sample','Choose a sample with a quick task: one calendar row, a copy before/after, or a short storyboard. Keep it aligned with the paid offer. Include a next step without hiding the resource behind unnecessary questions.',
 'Create a useful sample from [product/service]. It should solve [small task] in ten minutes and lead naturally to [paid next step]. Include a filled example, instructions, and a clear limit of scope. No exaggerated value amount.',
 'A sample page or file with a useful first action.','The sample works independently and previews the actual offer.'),
 step('Test delivery from the buyer side','Open the sample link in a signed-out browser and test the intended access. Check mobile readability, file permissions, and access instructions. For public samples, exclude client or account details. Record what you actually tested.',
 'Review these delivery steps [steps]. Identify permission, mobile, file-format, and broken-link risks. Write a short access message and a recovery message if the link fails. Do not claim any check was performed unless I confirm it.',
 'A verified sample link and fallback delivery message.','The resource is available to its intended audience with the intended permissions.'),
 step('Respond to requests clearly','If a post says comment a keyword, respond manually or use a verified eligible automation flow. Offer the requested link first. Ask one relevant question after delivery. Do not add people to a marketing list without the relevant consent.',
 'Write a manual response to someone asking for [sample]. Give [link], explain the quick task, then ask one optional question about their situation. Write a shorter public reply. No false claim of automated delivery.',
 'A resource response and one qualification question.','The user receives what the post promised.'),
 step('Bridge to the relevant offer','Use the person’s stated need to suggest the paid product or a service conversation. State price, contents, limitations, and next step. Answer objections honestly. Respect a refusal and avoid pressure from your own deadline.',
 'A prospect said [actual question]. My offer is [verified contents and price]. Draft a short helpful reply connecting their need to the offer. Include relevant limits. If the offer does not fit, say so. Do not invent urgency or guarantee results.',
 'A truthful offer reply and working checkout/proposal link.','The person knows exactly what they would receive and pay.'),
 step('Measure the whole path','Track requests, successful deliveries, useful conversations, checkout visits where available, sales, and collected net receipts. Use a distinct link or UTM per content source if supported. Review where people stop before changing every post.',
 'Here are real funnel counts [counts and date range]. Calculate request-to-delivery, delivery-to-conversation, and conversation-to-sale rates. Identify missing attribution. Suggest one improvement with a test plan. Separate small-sample observations from conclusions.',
 'One funnel review and next experiment.','Rates use matched time periods and known denominators. Sales are not treated as available payouts.')],
 {'title':'Worked example: Blueprint sample request','body':'Reply: “Here’s the worked example: [your sample link]. Start with the brief, then compare the raw caption with the edited version. Are you exploring client services or building your own product?” If services: “The Blueprint includes the prospecting steps, sample creation, scope, delivery, and follow-up. It is $97, one-time. Here is the page showing exactly what is included: [checkout/page].” This is a response to expressed interest, not a cold promise of earnings. Use the outreach tracker to log requests and actual purchases.', 'asset':'lead-replies.txt'},
 [('People ask for the link but do not buy','Find out what they wanted from the sample. Improve fit and the bridge to the offer, not pressure.'),('Automation is unavailable','Use the manual route. Do not advertise instant automated delivery until it works.'),('You need cash by a date','Check available balance, review status, withdrawal method, and processing estimate with your provider. Revenue and bank arrival are separate events.')],['A','B','E'])

book('J','affiliate-product-demo','Evaluate affiliate offers and TikTok Shop access','product',
 'Choose an eligible, understandable affiliate offer, make an honest demonstration, and track commission conditions. TikTok Shop is an optional market-specific branch.',
 ['Use a product you own or a program-provided demo you have permission to use. Apply only to programs supporting your country and payout method.', 'Film an honest comparison or demonstration and edit with available free tools. Commission is not instant cash.'],
 ['Claude Pro optionally compares supplied program terms. Higgsfield optionally supplies clearly illustrative context, never fabricated product use.', 'Pay for samples or production only after checking eligibility, commission, attribution, refund clawbacks, and payout timing. Avoid upfront purchases whose cost exceeds a realistic test budget.'],
 [step('Check eligibility before choosing a route','Open the platform’s current country-specific rules and account eligibility page. Confirm age, location, identity, followers where required, and payment method. US TikTok Shop rules apply to US-based creators and must not be assumed to cover Nigeria.',
 'Summarize these official program terms [text and source URL/date]. List eligibility, country, account type, payout method, commission timing, and missing requirements. Do not assume access from follower count alone. If unavailable, suggest an eligible independent affiliate route or a service offer.',
 'An eligibility checklist and go/no-go decision.','You use your real location and identity. No borrowed account or location workaround.'),
 step('Inspect the offer and unit economics','Read the commission terms, product quality, returns, price, cookie or attribution rules, and brand restrictions. Check real reviews and your own experience. Compare the cost of a sample with potential commission and the chance of refunds.',
 'Compare these verified offers [program terms and product observations]. Show commission per valid sale, costs, restrictions, payout delay, and risks. Mark unknowns. Recommend a small test only when eligibility and product quality are clear.',
 'One offer with documented terms and a budget.','You understand how a sale becomes an approved commission and when it becomes withdrawable.'),
 step('Create an honest demonstration','Show the actual product and an observable use. State limits and who it suits. Disclose the affiliate relationship clearly. Do not produce a synthetic customer pretending to have used it. AI is suitable for planning and illustrative scenes.',
 'Write a 30-second demo for [product I have used] from [observations]. Include use, one benefit I verified, one limitation, who it suits, and a clear affiliate disclosure. No invented personal experience, medical claims, or performance results.',
 'A truthful demo script with disclosure.','The footage and experience support the claims.'),
 step('Publish through the eligible route','For TikTok Shop, use the account’s Creator Center and approved Product Marketplace/showcase controls, then tag the eligible product. Check the market’s current posting and product rules. For an independent program, use its supplied trackable link and permitted channels.',
 'Make a publishing checklist from [official instructions] for my eligible route [route]. Include product/link selection, disclosure, content review, tracking, and a final preview. Do not invent interface labels or bypass account restrictions.',
 'A published demo with a valid attributed product/link.','The link opens the intended product and the relationship is disclosed.'),
 step('Review approved commissions, not views','Record clicks, attributed orders, returns, approved commission, costs, and funds available. Test another angle only after inspecting the product and tracking. Use the same content skill to offer product creative to businesses if affiliate access is unavailable.',
 'Analyze this actual affiliate data [rows]. Separate orders, pending commission, approved commission, refunds, and withdrawable funds. Calculate contribution after sample and production costs. Suggest one controlled follow-up experiment.',
 'An affiliate review and a stop/continue decision.','A high view count is not reported as income and pending commission is not counted as cash.')],
 {'title':'Worked example: access unavailable, skill still useful','body':'A creator in Nigeria should check the account’s current local eligibility instead of relying on US follower rules. If Shop access is unavailable, use a program that expressly accepts your location or offer businesses a scoped product-video service using H. For practice economics, a $30 product with 10% commission produces $3 per valid order. Twenty approved orders produce $60 gross commission before sample cost, production, refunds, and fees. This is arithmetic, not expected earnings.', 'asset':'affiliate-checklist.txt'},
 [('No TikTok Shop access','Use an eligible independent program or the product-creative service route. Do not spend a week on an unavailable channel.'),('Product cannot be tested','Do not claim personal use. Choose a product you can demonstrate or produce clearly labeled informational content.'),('Commissions remain pending','Read the program’s fulfillment, return, and payout conditions. Do not infer a next-day payout.')],['H','C','I'])
